   333	/** @brief Opens an existing Matlab MAT file
   334	 *
   335	 * Tries to open a Matlab MAT file with the given name
   336	 * @ingroup MAT
   337	 * @param matname Name of MAT file to open
   338	 * @param mode File access mode (MAT_ACC_RDONLY,MAT_ACC_RDWR,etc).
   339	 * @return A pointer to the MAT file or NULL if it failed.  This is not a
   340	 * simple FILE * and should not be used as one.
   341	 */
   342	mat_t *
   343	Mat_Open(const char *matname,int mode)
   344	{
   345	    FILE *fp = NULL;
   346	    mat_int16_t tmp, tmp2;
   347	    mat_t *mat = NULL;
   348	    size_t bytesread = 0;
   349	
   350	    if ( (mode & 0x01) == MAT_ACC_RDONLY ) {
   351	#if defined(_WIN32) && defined(_MSC_VER)
   352	        wchar_t* wname = utf82u(matname);
   353	        if ( NULL != wname ) {
   354	            fp = _wfopen(wname, L"rb");
   355	            free(wname);
   356	        }
   357	#else
   358	        fp = fopen(matname, "rb");
   359	#endif
   360	        if ( !fp )
   361	            return NULL;
   362	    } else if ( (mode & 0x01) == MAT_ACC_RDWR ) {
   363	#if defined(_WIN32) && defined(_MSC_VER)
   364	        wchar_t* wname = utf82u(matname);
   365	        if ( NULL != wname ) {
   366	            fp = _wfopen(wname, L"r+b");
   367	            free(wname);
   368	        }
   369	#else
   370	        fp = fopen(matname, "r+b");
   371	#endif
   372	        if ( !fp ) {
   373	            mat = Mat_CreateVer(matname,NULL,(enum mat_ft)(mode&0xfffffffe));
   374	            return mat;
   375	        }
   376	    } else {
   377	        Mat_Critical("Invalid file open mode");
   378	        return NULL;
   379	    }
   380	
   381	    mat = (mat_t*)malloc(sizeof(*mat));
   382	    if ( NULL == mat ) {
   383	        fclose(fp);
   384	        Mat_Critical("Couldn't allocate memory for the MAT file");
   385	        return NULL;
   386	    }
   387	
   388	    mat->fp = fp;
   389	    mat->header        = (char*)calloc(128,sizeof(char));
   390	    if ( NULL == mat->header ) {
   391	        free(mat);
   392	        fclose(fp);
   393	        Mat_Critical("Couldn't allocate memory for the MAT file header");
   394	        return NULL;
   395	    }
   396	    mat->subsys_offset = (char*)calloc(8,sizeof(char));
   397	    if ( NULL == mat->subsys_offset ) {
   398	        free(mat->header);
   399	        free(mat);
   400	        fclose(fp);
   401	        Mat_Critical("Couldn't allocate memory for the MAT file subsys offset");
   402	        return NULL;
   403	    }
   404	    mat->filename      = NULL;
   405	    mat->version       = 0;
   406	    mat->byteswap      = 0;
   407	    mat->num_datasets  = 0;
   408	#if defined(MAT73) && MAT73
   409	    mat->refs_id       = -1;
   410	#endif
   411	    mat->dir           = NULL;
   412	
   413	    bytesread += fread(mat->header,1,116,fp);
   414	    mat->header[116] = '\0';
   415	    bytesread += fread(mat->subsys_offset,1,8,fp);
   416	    bytesread += 2*fread(&tmp2,2,1,fp);
   417	    bytesread += fread(&tmp,1,2,fp);
