   491	        if ( (mode & 0x01) == MAT_ACC_RDONLY )
   492	            *(hid_t*)mat->fp=H5Fopen(matname,H5F_ACC_RDONLY,H5P_DEFAULT);
   493	        else if ( (mode & 0x01) == MAT_ACC_RDWR ) {
   494	            hid_t plist_ap;
